import { useState, useMemo } from "react";
import { 
  LayoutDashboard, Receipt, Coins, BarChart3, Settings, 
  TrendingUp, TrendingDown, Wallet, Package, Clock,
  Sun, Moon, Bell, Search, ChevronDown, User,
  ArrowUpRight, ArrowDownRight, Users, Store,
  Menu, X
} from "lucide-react";
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from "recharts";

export default function App() {
  const [dark, setDark] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [activeMenu, setActiveMenu] = useState("dashboard");

  const theme = useMemo(() => ({
    bg: dark ? "#0F172A" : "#F8FAFC",
    surface: dark ? "#1E293B" : "#FFFFFF",
    surfaceHover: dark ? "#334155" : "#F1F5F9",
    border: dark ? "#334155" : "#E2E8F0",
    text: dark ? "#F1F5F9" : "#0F172A",
    textSecondary: dark ? "#94A3B8" : "#64748B",
    textMuted: dark ? "#64748B" : "#94A3B8",
    accent: "#0D9488",
    accentBg: dark ? "#134E4A" : "#CCFBF1",
    accentHover: "#0F766E",
    success: "#059669",
    successBg: dark ? "#064E3B" : "#D1FAE5",
    danger: "#DC2626",
    dangerBg: dark ? "#7F1D1D" : "#FEE2E2",
    warning: "#D97706",
    warningBg: dark ? "#78350F" : "#FEF3C7",
    sidebar: dark ? "#0F172A" : "#1E293B",
    sidebarHover: dark ? "#1E293B" : "#334155",
    sidebarActive: "#0D9488",
    sidebarText: "#CBD5E1",
    sidebarTextActive: "#FFFFFF",
    cardShadow: dark ? "0 1px 2px rgba(0,0,0,0.3)" : "0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04)",
    kpiGlow: dark ? "0 4px 20px rgba(13,148,136,0.15)" : "0 4px 20px rgba(13,148,136,0.08)"
  }), [dark]);

  const chartData = [
    { day: "T2", thu: 3200000, chi: 2100000 },
    { day: "T3", thu: 4500000, chi: 1800000 },
    { day: "T4", thu: 2800000, chi: 3400000 },
    { day: "T5", thu: 6100000, chi: 2500000 },
    { day: "T6", thu: 5200000, chi: 1900000 },
    { day: "T7", thu: 3800000, chi: 4200000 },
    { day: "CN", thu: 1500000, chi: 800000 },
  ];

  const menuItems = [
    { id: "dashboard", label: "Tổng quan", icon: LayoutDashboard },
    { id: "expense", label: "Chi phí", icon: Receipt, badge: "12" },
    { id: "revenue", label: "Doanh thu", icon: Coins, badge: "8" },
    { id: "customers", label: "Khách hàng", icon: Users },
    { id: "products", label: "Sản phẩm", icon: Package },
    { id: "platforms", label: "Kênh bán", icon: Store },
    { id: "report", label: "Báo cáo", icon: BarChart3 },
    { id: "settings", label: "Cài đặt", icon: Settings },
  ];

  const kpiCards = [
    { title: "Tổng thu", value: "27.100.000", icon: TrendingUp, color: theme.success, bg: theme.successBg, change: "+12.5%" },
    { title: "Tổng chi", value: "17.900.000", icon: TrendingDown, color: theme.danger, bg: theme.dangerBg, change: "+3.2%" },
    { title: "Lợi nhuận", value: "9.200.000", icon: Wallet, color: theme.accent, bg: theme.accentBg, change: "+24.8%" },
    { title: "Công nợ", value: "4.500.000", icon: Clock, color: theme.warning, bg: theme.warningBg, change: "3 đơn" },
  ];

  const recentTx = [
    { desc: "Đơn hàng #DH086", cat: "Shopee", amount: "1.250.000", type: "in" },
    { desc: "Tiền điện tháng 7", cat: "Hóa đơn", amount: "890.000", type: "out" },
    { desc: "Đơn hàng #DH087", cat: "Lazada", amount: "2.100.000", type: "in" },
    { desc: "Văn phòng phẩm", cat: "Vận hành", amount: "450.000", type: "out" },
  ];

  const formatVnd = (v: number) => {
    if (v >= 1000000) return `${(v/1000000).toFixed(1)}M`;
    if (v >= 1000) return `${(v/1000).toFixed(0)}K`;
    return String(v);
  };

  const sidebarW = sidebarOpen ? 240 : 64;

  return (
    <>
      <style>{`
        * { box-sizing: border-box; margin: 0; padding: 0; }
        body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; }
        .scroll-thin::-webkit-scrollbar { width: 4px; }
        .scroll-thin::-webkit-scrollbar-thumb { background: ${theme.textMuted}; border-radius: 2px; }
        .scroll-thin::-webkit-scrollbar-track { background: transparent; }
        .menu-item { transition: all 150ms ease; }
        .menu-item:hover { background: ${theme.sidebarHover}; }
        .card-hover { transition: all 200ms ease; }
        .card-hover:hover { transform: translateY(-2px); box-shadow: ${theme.kpiGlow}; }
        @container (max-width: 400px) {
          .kpi-grid { grid-template-columns: 1fr 1fr; }
        }
        @container (max-width: 320px) {
          .kpi-grid { grid-template-columns: 1fr; }
          .chart-area { height: 160px; }
        }
      `}</style>
      <div style={{
        width: "100%", height: "100%",
        display: "flex",
        background: theme.bg,
        color: theme.text,
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif",
        fontSize: 13,
        lineHeight: 1.45,
        overflow: "hidden",
        containerType: "inline-size"
      }}>
        {/* Sidebar */}
        <div style={{
          width: sidebarW,
          minWidth: sidebarW,
          background: theme.sidebar,
          display: "flex",
          flexDirection: "column",
          transition: "width 200ms ease",
          overflow: "hidden",
          borderRight: `1px solid ${dark ? "#1E293B" : "#334155"}`
        }}>
          {/* Logo */}
          <div style={{
            display: "flex", alignItems: "center", gap: 10,
            padding: "16px 16px", height: 56,
            borderBottom: `1px solid ${dark ? "#1E293B" : "#334155"}`
          }}>
            <div style={{
              width: 32, height: 32, borderRadius: 8,
              background: "linear-gradient(135deg, #0D9488, #14B8A6)",
              display: "flex", alignItems: "center", justifyContent: "center",
              fontSize: 16, fontWeight: 700, color: "#FFF",
              flexShrink: 0
            }}>T</div>
            {sidebarOpen && (
              <span style={{ color: "#F1F5F9", fontWeight: 700, fontSize: 15, whiteSpace: "nowrap" }}>
                Thu Chi
              </span>
            )}
          </div>

          {/* Menu */}
          <nav style={{ flex: 1, padding: "8px", overflowY: "auto" }} className="scroll-thin">
            {menuItems.map((item) => {
              const Icon = item.icon;
              const active = activeMenu === item.id;
              return (
                <button
                  key={item.id}
                  className="menu-item"
                  onClick={() => setActiveMenu(item.id)}
                  style={{
                    width: "100%", display: "flex", alignItems: "center", gap: 10,
                    padding: sidebarOpen ? "9px 12px" : "9px",
                    borderRadius: 8, border: "none", cursor: "pointer",
                    background: active ? theme.sidebarActive : "transparent",
                    color: active ? theme.sidebarTextActive : theme.sidebarText,
                    fontSize: 13, fontWeight: active ? 600 : 400,
                    justifyContent: sidebarOpen ? "flex-start" : "center",
                    marginBottom: 2
                  }}
                >
                  <Icon size={18} style={{ flexShrink: 0 }} />
                  {sidebarOpen && (
                    <>
                      <span style={{ flex: 1, textAlign: "left", whiteSpace: "nowrap" }}>{item.label}</span>
                      {item.badge && (
                        <span style={{
                          background: active ? "rgba(255,255,255,0.2)" : "rgba(255,255,255,0.08)",
                          color: active ? "#FFF" : theme.sidebarText,
                          fontSize: 11, padding: "1px 7px", borderRadius: 10,
                          fontWeight: 500
                        }}>{item.badge}</span>
                      )}
                    </>
                  )}
                </button>
              );
            })}
          </nav>

          {/* User */}
          <div style={{
            padding: "12px", borderTop: `1px solid ${dark ? "#1E293B" : "#334155"}`,
            display: "flex", alignItems: "center", gap: 10
          }}>
            <div style={{
              width: 32, height: 32, borderRadius: "50%",
              background: "linear-gradient(135deg, #0D9488, #F59E0B)",
              display: "flex", alignItems: "center", justifyContent: "center",
              color: "#FFF", fontWeight: 600, fontSize: 12,
              flexShrink: 0
            }}>QT</div>
            {sidebarOpen && (
              <div style={{ minWidth: 0 }}>
                <div style={{ color: "#F1F5F9", fontSize: 12, fontWeight: 500, whiteSpace: "nowrap" }}>Quốc Trần</div>
                <div style={{ color: "#94A3B8", fontSize: 10, whiteSpace: "nowrap" }}>Chủ cửa hàng</div>
              </div>
            )}
          </div>
        </div>

        {/* Main content */}
        <div style={{ flex: 1, display: "flex", flexDirection: "column", minWidth: 0, overflow: "hidden" }}>
          {/* Top bar */}
          <header style={{
            height: 56, display: "flex", alignItems: "center", gap: 12,
            padding: "0 20px", background: theme.surface,
            borderBottom: `1px solid ${theme.border}`,
            flexShrink: 0
          }}>
            <button
              onClick={() => setSidebarOpen(!sidebarOpen)}
              style={{
                border: "none", background: "transparent", cursor: "pointer",
                color: theme.textSecondary, padding: 4, borderRadius: 6,
                display: "flex"
              }}
            >
              {sidebarOpen ? <X size={18} /> : <Menu size={18} />}
            </button>
            <div style={{ flex: 1, minWidth: 0 }}>
              <h1 style={{ fontSize: 16, fontWeight: 700, color: theme.text }}>Tổng quan</h1>
              <p style={{ fontSize: 11, color: theme.textMuted }}>Xin chào, Quốc Trần 👋</p>
            </div>
            <div style={{
              display: "flex", alignItems: "center", gap: 4,
              background: theme.bg, borderRadius: 8, padding: "4px 10px",
              border: `1px solid ${theme.border}`
            }}>
              <Search size={14} style={{ color: theme.textMuted }} />
              <span style={{ fontSize: 12, color: theme.textMuted }}>Tìm kiếm... (⌘K)</span>
            </div>
            <button
              onClick={() => setDark(!dark)}
              style={{
                border: "none", background: "transparent", cursor: "pointer",
                color: theme.textSecondary, padding: 6, borderRadius: 6,
                display: "flex"
              }}
            >
              {dark ? <Sun size={16} /> : <Moon size={16} />}
            </button>
            <button style={{
              border: "none", background: "transparent", cursor: "pointer",
              color: theme.textSecondary, padding: 6, borderRadius: 6,
              display: "flex", position: "relative"
            }}>
              <Bell size={16} />
              <span style={{
                position: "absolute", top: 2, right: 2,
                width: 7, height: 7, borderRadius: "50%",
                background: theme.danger, border: `2px solid ${theme.surface}`
              }} />
            </button>
          </header>

          {/* Dashboard content */}
          <div style={{
            flex: 1, overflowY: "auto", padding: "20px",
            display: "flex", flexDirection: "column", gap: 20
          }} className="scroll-thin">
            {/* KPI Cards */}
            <div className="kpi-grid" style={{
              display: "grid",
              gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))",
              gap: 14
            }}>
              {kpiCards.map((card) => {
                const Icon = card.icon;
                return (
                  <div
                    key={card.title}
                    className="card-hover"
                    style={{
                      background: theme.surface,
                      borderRadius: 12,
                      padding: "16px",
                      boxShadow: theme.cardShadow,
                      display: "flex", alignItems: "center", gap: 12,
                      border: `1px solid ${theme.border}`,
                      cursor: "pointer"
                    }}
                  >
                    <div style={{
                      width: 42, height: 42, borderRadius: 10,
                      background: card.bg,
                      display: "flex", alignItems: "center", justifyContent: "center",
                      flexShrink: 0
                    }}>
                      <Icon size={20} style={{ color: card.color }} />
                    </div>
                    <div style={{ minWidth: 0, flex: 1 }}>
                      <div style={{ fontSize: 11, color: theme.textMuted, marginBottom: 2 }}>{card.title}</div>
                      <div style={{
                        fontSize: 18, fontWeight: 700, color: theme.text,
                        fontVariantNumeric: "tabular-nums",
                        lineHeight: 1.2
                      }}>
                        {card.value}
                      </div>
                      <div style={{ fontSize: 11, color: card.color, fontWeight: 500, marginTop: 1 }}>
                        {card.change}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>

            {/* Chart + Recent Tx row */}
            <div style={{
              display: "grid",
              gridTemplateColumns: "minmax(0, 2fr) minmax(260px, 1fr)",
              gap: 14
            }}>
              {/* Chart */}
              <div className="chart-area" style={{
                background: theme.surface,
                borderRadius: 12,
                padding: "20px",
                boxShadow: theme.cardShadow,
                border: `1px solid ${theme.border}`,
                minHeight: 260
              }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
                  <div>
                    <h3 style={{ fontSize: 14, fontWeight: 600, color: theme.text }}>Thu chi 7 ngày</h3>
                    <p style={{ fontSize: 11, color: theme.textMuted, marginTop: 2 }}>Tuần này</p>
                  </div>
                  <span style={{
                    fontSize: 11, padding: "3px 10px", borderRadius: 20,
                    background: theme.accentBg, color: theme.accent,
                    fontWeight: 500
                  }}>+24.8%</span>
                </div>
                <ResponsiveContainer width="100%" height="85%">
                  <AreaChart data={chartData} margin={{ top: 4, right: 4, left: -20, bottom: 0 }}>
                    <defs>
                      <linearGradient id="gradientThu" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#0D9488" stopOpacity={0.2}/>
                        <stop offset="95%" stopColor="#0D9488" stopOpacity={0}/>
                      </linearGradient>
                      <linearGradient id="gradientChi" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#F59E0B" stopOpacity={0.2}/>
                        <stop offset="95%" stopColor="#F59E0B" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" stroke={theme.border} vertical={false} />
                    <XAxis dataKey="day" tick={{ fontSize: 11, fill: theme.textMuted }} axisLine={false} tickLine={false} />
                    <YAxis tick={{ fontSize: 10, fill: theme.textMuted }} axisLine={false} tickLine={false} tickFormatter={formatVnd} width={40} />
                    <Tooltip
                      formatter={(value: number) => [`${value.toLocaleString("vi-VN")} ₫`, ""]}
                      contentStyle={{
                        background: dark ? "#1E293B" : "#FFF",
                        border: `1px solid ${theme.border}`,
                        borderRadius: 8, fontSize: 12,
                        color: theme.text,
                        boxShadow: theme.cardShadow
                      }}
                    />
                    <Area type="monotone" dataKey="thu" name="Thu" stroke="#0D9488" strokeWidth={2} fill="url(#gradientThu)" />
                    <Area type="monotone" dataKey="chi" name="Chi" stroke="#F59E0B" strokeWidth={2} fill="url(#gradientChi)" />
                  </AreaChart>
                </ResponsiveContainer>
              </div>

              {/* Recent Transactions */}
              <div style={{
                background: theme.surface,
                borderRadius: 12,
                padding: "20px",
                boxShadow: theme.cardShadow,
                border: `1px solid ${theme.border}`,
                display: "flex", flexDirection: "column",
                minWidth: 0
              }}>
                <div style={{ marginBottom: 14 }}>
                  <h3 style={{ fontSize: 14, fontWeight: 600, color: theme.text }}>Giao dịch gần đây</h3>
                  <p style={{ fontSize: 11, color: theme.textMuted, marginTop: 2 }}>4 giao dịch mới nhất</p>
                </div>
                <div style={{ display: "flex", flexDirection: "column", gap: 8, flex: 1 }}>
                  {recentTx.map((tx, i) => (
                    <div key={i} style={{
                      display: "flex", alignItems: "center", gap: 10,
                      padding: "8px 10px", borderRadius: 8,
                      background: theme.surfaceHover,
                      transition: "background 150ms ease"
                    }}>
                      <div style={{
                        width: 32, height: 32, borderRadius: "50%",
                        background: tx.type === "in" ? theme.successBg : theme.dangerBg,
                        display: "flex", alignItems: "center", justifyContent: "center",
                        flexShrink: 0
                      }}>
                        {tx.type === "in"
                          ? <ArrowUpRight size={14} style={{ color: theme.success }} />
                          : <ArrowDownRight size={14} style={{ color: theme.danger }} />
                        }
                      </div>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{ fontSize: 12, fontWeight: 500, color: theme.text, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{tx.desc}</div>
                        <div style={{ fontSize: 10, color: theme.textMuted }}>{tx.cat}</div>
                      </div>
                      <span style={{
                        fontSize: 12, fontWeight: 600,
                        fontVariantNumeric: "tabular-nums",
                        color: tx.type === "in" ? theme.success : theme.danger,
                        whiteSpace: "nowrap"
                      }}>
                        {tx.type === "in" ? "+" : "−"}{tx.amount}
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Footer note */}
            <div style={{
              textAlign: "center", padding: "8px",
              fontSize: 10, color: theme.textMuted
            }}>
              © 2026 Quản Lý Tài Chính · v2.0 · Preview thiết kế mới
            </div>
          </div>
        </div>
      </div>
    </>
  );
}
